WITH car AS (SELECT REPLACE(a.id_imovel,'-','') id_car_norm,a.id_imovel,a.id_municipio,a.area,SAFE_DIVIDE(ST_AREA(a.geometria),10000) area_geometria_ha FROM `basedosdados.br_sfb_sicar.area_imovel` a WHERE a.id_municipio='2929701' AND a.data_extracao>=DATE '2026-06-02' AND a.data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(a.id_imovel,'-','') ORDER BY a.data_extracao DESC)=1),p AS (SELECT DISTINCT ano_emissao,id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm,cpf,cnpj_basico FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao BETWEEN 2019 AND 2024 AND id_car IS NOT NULL AND TRIM(id_car)!=''),n AS (SELECT ano_emissao,id_referencia_bacen,numero_ordem,COUNT(*) n_imoveis FROM p GROUP BY 1,2,3),mut AS (SELECT id_referencia_bacen,STRING_AGG(DISTINCT CASE WHEN cpf IS NOT NULL AND cpf!='' THEN CONCAT('M_',SUBSTR(TO_HEX(SHA256(cpf)),1,10)) WHEN cnpj IS NOT NULL AND cnpj!='' THEN CONCAT('M_',SUBSTR(TO_HEX(SHA256(cnpj)),1,10)) END,', ') mutuarios FROM `basedosdados.br_bcb_sicor.recurso_publico_mutuario` WHERE ano_emissao BETWEEN 2019 AND 2024 GROUP BY 1),op AS (SELECT p.ano_emissao,p.id_referencia_bacen,p.numero_ordem,p.id_car_norm,p.cpf,p.cnpj_basico,op.valor_parcela_credito,e.produto,e.finalidade,mut.mutuarios FROM p JOIN `basedosdados.br_bcb_sicor.operacao` op USING(ano_emissao,id_referencia_bacen,numero_ordem) LEFT JOIN mut USING(id_referencia_bacen) LEFT JOIN `basedosdados.br_bcb_sicor.empreendimento` e USING(id_empreendimento) WHERE op.ano_emissao BETWEEN 2019 AND 2024),lib AS (SELECT id_referencia_bacen,numero_ordem,SUM(valor_liberado) valor_liberado FROM `basedosdados.br_bcb_sicor.liberacao` WHERE ano BETWEEN 2019 AND 2024 AND mes BETWEEN 1 AND 12 GROUP BY 1,2),ag AS (SELECT id_referencia_bacen,STRING_AGG(DISTINCT CONCAT('AG_',SUBSTR(TO_HEX(SHA256(cnpj_agencia)),1,10)),', ') agencias FROM `basedosdados.br_bcb_sicor.recurso_publico_complemento_operacao` WHERE ano_emissao BETWEEN 2019 AND 2024 GROUP BY 1),b AS (SELECT op.*,c.id_imovel,c.area,c.area_geometria_ha,COALESCE(lib.valor_liberado,0) valor_liberado,ag.agencias FROM op JOIN car c USING(id_car_norm) LEFT JOIN lib USING(id_referencia_bacen,numero_ordem) LEFT JOIN ag USING(id_referencia_bacen) WHERE c.area<0.1) SELECT id_imovel,area,area_geometria_ha,COUNT(DISTINCT id_referencia_bacen) operacoes,COUNT(*) linhas,COUNT(DISTINCT COALESCE(NULLIF(cpf,''),NULLIF(cnpj_basico,''))) proprietarios,COUNT(DISTINCT mutuarios) mutuarios_operacao,SUM(valor_parcela_credito) valor_original,SUM(valor_liberado) valor_liberado,MIN(ano_emissao) primeiro_ano,MAX(ano_emissao) ultimo_ano,STRING_AGG(DISTINCT produto,', ' ORDER BY produto) produtos,STRING_AGG(DISTINCT finalidade,', ' ORDER BY finalidade) finalidades,STRING_AGG(DISTINCT agencias,', ') agencias FROM b GROUP BY 1,2,3 ORDER BY operacoes DESC,mutuarios_operacao DESC,valor_original DESC